+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/**
+ * Which customers a query should return.
+ *
+ * @param name     text to search for. It is split on whitespace into terms, and
+ *                 every term must appear in the customer's first name or last
+ *                 name. Case and accents are ignored. Blank matches everyone.
+ * @param statuses statuses to accept. Empty accepts every status.
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null) ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /** Whether {@code customer} satisfies both the name and the status filter. */
+    public boolean matches(Customer customer) {
+        return (statuses.isEmpty() || statuses.contains(customer.status()))
+                && nameMatches(customer);
+    }
+
+    private boolean nameMatches(Customer customer) {
+        String folded = fold(name).strip();
+        if (folded.isEmpty()) {
+            return true;
+        }
+        String first = fold(customer.firstName());
+        String last = fold(customer.lastName());
+        for (String term : folded.split("\\s+")) {
+            if (!first.contains(term) && !last.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /** Lower-cases {@code text} and strips accents, so that {@code Mäkinen} folds to {@code makinen}. */
+    private static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
