+/**
+ * Drives the running application in a real, offline Chromium. Some of what the
+ * filter does is only visible there: the address bar, the history and what
+ * typing costs the backend.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListBrowserTest {
+
+    private static Playwright playwright;
+    private static Browser browser;
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    private Page page;
+
+    @BeforeAll
+    static void launchBrowser() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch();
+    }
+
+    @AfterAll
+    static void closeBrowser() {
+        browser.close();
+        playwright.close();
+    }
+
+    @BeforeEach
+    void openPage() {
+        page = browser.newPage();
+    }
+
+    @Test
+    void typedNameIsReflectedInTheAddressBarWithoutAddingHistory() {
+        open("/");
+        page.getByText("Showing 500 of 500").waitFor();
+        int historyBefore = historyLength();
+
+        nameField().fill("ada aal");
+
+        page.getByText("Showing 2 of 500").waitFor();
+        page.waitForURL(url -> url.contains("name=ada"));
+        assertEquals(historyBefore, historyLength());
+    }
+
+    @Test
+    void clearingTheNameRemovesItFromTheAddressBar() {
+        open("/?name=vir");
+        page.getByText("Showing 15 of 500").waitFor();
+
+        nameField().fill("");
+
+        page.getByText("Showing 500 of 500").waitFor();
+        page.waitForURL(url -> !url.contains("name="));
+    }
+
+    @Test
+    void openingTheAddressRestoresBothFilters() {
+        open("/?name=vir&status=ACTIVE,CLOSED");
+
+        page.getByText("Showing 10 of 500").waitFor();
+        assertEquals("vir", nameField().inputValue());
+        assertEquals(2, ((Number) page.locator("vaadin-multi-select-combo-box").first()
+                .evaluate("element => element.selectedItems.length")).intValue());
+    }
+
+    @Test
+    void typingANameCostsAtMostTwoQueries() {
+        open("/");
+        page.getByText("Showing 500 of 500").waitFor();
+        queryLog.clear();
+
+        nameField().pressSequentially("josephine");
+
+        page.getByText("Showing 12 of 500").waitFor();
+        page.waitForTimeout(500);
+        assertTrue(queryLog.countQueries().size() <= 2,
+                "Typing a nine-letter name asked the backend for counts " + queryLog.countQueries());
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing a nine-letter name asked the backend for pages " + queryLog.pageQueries());
+    }
+
+    private void open(String path) {
+        page.navigate("http://localhost:" + port + path);
+    }
+
+    private Locator nameField() {
+        return page.locator("input[placeholder='Filter by name']");
+    }
+
+    private int historyLength() {
+        return ((Number) page.evaluate("history.length")).intValue();
+    }
+}
